pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testRegression_property() public {
        vm.deal(address(this), 10);
        vm.warp(1);
        vm.warp(12345);
        vm.roll(67890);
        vm.deal(address(0xdead), 10);
        vm.prank(address(0xdead));
        bool ok;
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.warp(1);
        vm.roll(1);
        address player = address(0x01);
        vm.deal(player, 10);
        vm.prank(player);
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }
        address player2 = address(0x02);
        vm.warp(2);
        vm.roll(0);
        vm.deal(player2, 10);
        vm.prank(player2);
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
